import subprocess
import ftplib
import os

def task_func(ftp_server='ftp.dlptest.com', ftp_user='dlpuser', ftp_password='rNrKYTX9g7z3RgJRmxWuGHbeu', ftp_dir='/ftp/test'):
    try:
        # Connect to the FTP server
        ftp = ftplib.FTP(ftp_server)
    except Exception as e:
        raise Exception(f"Failed to connect to FTP server {ftp_server}: {str(e)}")

    try:
        # Log in to the FTP server
        ftp.login(user=ftp_user, passwd=ftp_password)
    except Exception as e:
        raise Exception(f"Failed to log into FTP server {ftp_server} with user {ftp_user}: {str(e)}")

    try:
        # Change to the specified directory
        ftp.cwd(ftp_dir)
    except Exception as e:
        raise Exception(f"Failed to change to directory {ftp_dir} on server {ftp_server}: {str(e)}")

    try:
        # List files in the directory
        filenames = ftp.nlst()
    except Exception as e:
        raise Exception(f"Failed to list files in directory {ftp_dir} on server {ftp_server}: {str(e)}")

    # Close the FTP connection
    ftp.quit()

    # Download files using wget in a subprocess
    downloaded_files = []
    for filename in filenames:
        try:
            # Construct the FTP URL for the file
            file_url = f"ftp://{ftp_user}:{ftp_password}@{ftp_server}{ftp_dir}/{filename}"

            # Use wget to download the file
            subprocess.run(['wget', file_url], check=True)

            # Add the filename to the list of downloaded files
            downloaded_files.append(filename)
        except subprocess.CalledProcessError as e:
            print(f"Failed to download file {filename} from {ftp_server}: {str(e)}")

    return downloaded_files

import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    """
    Compress all files in the specified source folder and move the compressed files
    to a destination folder. This operation is executed as a background process using
    the 'gzip' command.

    Args:
        src_folder (str): Path to the source folder containing files to compress.
        dst_folder (str): Path to the destination folder to move compressed files.

    Returns:
        dict: A dictionary containing:
            'success' (bool): True if all files were compressed and moved successfully, False otherwise.
            'message' (str): A descriptive message about the operation's result.
            'failed_files' (list): A list of filenames that failed to compress or move.
    """
    # Ensure the source and destination folders exist
    if not os.path.isdir(src_folder):
        return {
            'success': False,
            'message': f"Source folder '{src_folder}' does not exist.",
            'failed_files': []
        }
    if not os.path.isdir(dst_folder):
        os.makedirs(dst_folder)

    # Get a list of all files in the source folder
    files = glob(os.path.join(src_folder, '*'))
    failed_files = []

    for file_path in files:
        if os.path.isfile(file_path):
            try:
                # Compress the file using gzip
                subprocess.run(['gzip', file_path], check=True)

                # Move the compressed file to the destination folder
                compressed_file = file_path + '.gz'
                if os.path.exists(compressed_file):
                    shutil.move(compressed_file, os.path.join(dst_folder, os.path.basename(compressed_file)))
                else:
                    failed_files.append(os.path.basename(file_path))
            except subprocess.CalledProcessError:
                failed_files.append(os.path.basename(file_path))
            except Exception as e:
                failed_files.append(os.path.basename(file_path))

    # Determine the success of the operation
    if not failed_files:
        return {
            'success': True,
            'message': "All files were compressed and moved successfully.",
            'failed_files': []
        }
    else:
        return {
            'success': False,
            'message': f"Some files failed to compress or move. {len(failed_files)} file(s) failed.",
            'failed_files': failed_files
        }
